<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { api, json, user } from '../api/client';
import type { ModelIn, ModelOut } from '../api/contracts';
import { report, success } from '../composables/ui';
import PageHeading from '../components/PageHeading.vue';
const loading = ref(true), saving = ref(false), configured = ref(false), hasCredential = ref(false), credential = ref(''), clearCredential = ref(false), showCredential = ref(false);
const form = reactive<ModelIn>({ provider: 'openai-compatible', endpoint: 'https://api.openai.com/v1', model: '', max_input_chars: 12000, max_output_tokens: 2000, daily_requests: 20 });
const providers = [{ label: 'OpenAI-compatible endpoint', value: 'openai-compatible' }, { label: 'OpenAI', value: 'openai' }, { label: 'Anthropic', value: 'anthropic' }, { label: 'Google', value: 'google' }, { label: 'Ollama', value: 'ollama' }];
async function load() { try { const data = await api<ModelOut | null>('/model'); if (data) { Object.assign(form, data); configured.value = true; hasCredential.value = data.has_credential; } } catch (err) { report(err); } finally { loading.value = false; } }
function changeProvider() { const endpoints: Record<string, string> = { 'openai-compatible': 'https://api.openai.com/v1', openai: 'https://api.openai.com/v1', anthropic: 'https://api.anthropic.com', google: 'https://generativelanguage.googleapis.com', ollama: 'http://127.0.0.1:11434/v1' }; form.endpoint = endpoints[form.provider]!; }
async function save() {
  saving.value = true;
  try { const payload: ModelIn = { provider: form.provider, endpoint: form.endpoint, model: form.model, max_input_chars: Number(form.max_input_chars), max_output_tokens: Number(form.max_output_tokens), daily_requests: Number(form.daily_requests) }; if (credential.value || clearCredential.value) payload.credential = clearCredential.value ? '' : credential.value; const data = await api<ModelOut>('/model', json(payload, 'PUT')); configured.value = true; hasCredential.value = data.has_credential; credential.value = ''; clearCredential.value = false; success('Model settings saved'); }
  catch (err) { report(err); }
  finally { saving.value = false; }
}
async function disconnect() { saving.value = true; try { await api('/model', { method: 'DELETE' }); configured.value = false; hasCredential.value = false; credential.value = ''; success('Model disconnected and credential removed'); } catch (err) { report(err); } finally { saving.value = false; } }
onMounted(() => void load());
</script>
<template>
  <q-page class="page settings-page"><PageHeading title="Make it your own" subtitle="Choose how unstructured news becomes something you can follow." /><q-linear-progress v-if="loading" indeterminate /><div class="settings-grid"><q-form class="settings-form info-panel" @submit="save"><div class="settings-title"><span class="summary-icon purple"><q-icon name="psychology" /></span><div><h2>Bring your own model</h2><p>Optional extraction, with a review before publication.</p></div><span v-if="configured" class="trust-badge confirmed">Connected</span></div><div class="form-stack"><q-select v-model="form.provider" :options="providers" emit-value map-options outlined label="Provider" @update:model-value="changeProvider" /><q-input v-model="form.endpoint" outlined label="Endpoint" :rules="[value => !!value || 'Enter an endpoint']" /><q-input v-model="form.model" outlined label="Model identifier" placeholder="Use the exact ID supported by your provider" :rules="[value => !!value || 'Enter a model identifier']" /><q-input v-model="credential" :type="showCredential ? 'text' : 'password'" outlined label="API credential" autocomplete="new-password" :hint="hasCredential ? 'A credential is saved. Leave this empty to keep it.' : 'Stored encrypted; never included in API responses.'"><template #append><q-btn flat round size="sm" :icon="showCredential ? 'visibility_off' : 'visibility'" :aria-label="showCredential ? 'Hide credential' : 'Show credential'" @click="showCredential = !showCredential" /></template></q-input><q-checkbox v-if="hasCredential" v-model="clearCredential" label="Remove the saved credential" /><h3 class="form-subheading">Usage limits</h3><div class="budget-fields"><q-input v-model.number="form.daily_requests" outlined type="number" min="1" max="1000" label="Extractions / day" /><q-input v-model.number="form.max_input_chars" outlined type="number" min="1000" max="30000" label="Input characters" /><q-input v-model.number="form.max_output_tokens" outlined type="number" min="100" max="8000" label="Output tokens" /></div><div class="settings-actions"><q-btn v-if="configured" flat no-caps color="negative" label="Disconnect model" :disable="saving" @click="disconnect" /><q-space /><q-btn unelevated color="primary" no-caps label="Save model settings" type="submit" :loading="saving" /></div></div></q-form><aside><section class="info-panel"><div class="eyebrow">HOW EXTRACTION WORKS</div><h2>From article to evidence</h2><ol class="extraction-steps"><li><strong>Submit a source</strong><span>The worker collects article text.</span></li><li><strong>Extract proposed claims</strong><span>Your model returns dates, event types, and exact supporting quotations.</span></li><li><strong>Review the evidence</strong><span>You approve, correct, or reject each claim.</span></li></ol><q-btn flat color="primary" no-caps icon="add_link" label="Submit an article" to="/sources" /></section><section class="info-panel"><h2>Running a local model?</h2><p>A hosted worker’s <code>localhost</code> is the server itself. Run a local worker beside the model or use a reachable endpoint enabled by your administrator.</p><p>Your server controls allowed model hosts. Loopback access requires the local-model setting.</p></section><section class="info-panel"><h2>Your account</h2><p><strong>{{ user?.username }}</strong><br />{{ user?.is_staff ? 'Curator account' : 'Personal account' }}</p><p>Progress, saved views, model credentials, and reviewed claims belong to your account.</p><a v-if="user?.is_staff" href="/admin/" target="_blank" rel="noopener noreferrer">Open catalogue administration <q-icon name="open_in_new" /></a></section></aside></div></q-page>
</template>
